#include <iostream>
#include <queue>
#include <cstring>
#include <vector>
#include <algorithm>
using namespace std;

const int MaxSize = 202, Infinite = 0x3f3f3f3f;

int EdgeFlow[MaxSize][MaxSize], EdgeCap[MaxSize][MaxSize], Parent[MaxSize], Q[MaxSize], Dist[MaxSize];

int FF_Algorithm(int Nodes, int S, int T) {
    while (true) {
        memset(Parent, -1, sizeof(Parent));
        Dist[S] = Infinite;
        int h = 0, t = 0;
        Q[t++] = S;
        while (h < t && Parent[T] < 0) {
            int u = Q[h++];
            for (int v = 0; v < Nodes; ++v) {
                if (Parent[v] < 0) {
                    int rc = EdgeCap[u][v] - EdgeFlow[u][v];
                    if (rc > 0) {
                        Parent[Q[t++] = v] = u;
                        Dist[v] = min(Dist[u], rc);
                    }
                }
            }
        }
        if (Parent[T] < 0) break;
        int delta = Dist[T];
        for (int cur = T; cur != S; cur = Parent[cur]) {
            EdgeFlow[Parent[cur]][cur] += delta;
            EdgeFlow[cur][Parent[cur]] -= delta;
        }
    }
    int sum = 0;
    for (int k = 0; k < Nodes; ++k) sum += EdgeFlow[S][k];
    return sum;
}

char GridIn[11][11], GridOut[11][11];
int Zr, Zc, DRow[4] = {0, 0, 1, -1}, DCol[4] = {1, -1, 0, 0};
int DistGrid[101][101];
int N, Tval;
vector<int> SRows, SCols;

void BFS(int sr, int sc, int* out, bool condCheck) {
    queue<pair<int,int>> q;
    out[sr*N + sc] = 0;
    q.push({sr, sc});
    while (!q.empty()) {
        auto [r, c] = q.front(); q.pop();
        int idx = r*N + c;
        int d = out[idx];
        if (condCheck && (DistGrid[Zr*N + Zc][idx] <= d || Tval <= d)) {
            if (DistGrid[Zr*N + Zc][idx] < d || Tval < d)
                out[idx] = Infinite + 1;
            continue;
        }
        for (int i = 0; i < 4; ++i) {
            int nr = r + DRow[i], nc = c + DCol[i];
            if (nr < 0 || nc < 0 || nr == N || nc == N) continue;
            char ch = GridOut[nr][nc];
            if (ch < '0' || ch > '9') continue;
            int nidx = nr*N + nc;
            if (out[nidx] != Infinite) continue;
            out[nidx] = d + 1;
            q.push({nr, nc});
        }
    }
}

void BuildGraph() {
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            char c = GridOut[i][j];
            if (c >= '1' && c <= '9') {
                SRows.push_back(i);
                SCols.push_back(j);
                int idx = i*N + j;
                EdgeCap[idx + 2 + N*N][1] = c - '0';
            }
        }
    }
    int zIdx = Zr*N + Zc;
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            char c = GridIn[i][j];
            if (c >= '1' && c <= '9') {
                int idx = i*N + j;
                EdgeCap[0][idx + 2] = c - '0';
                for (int k = 0; k < SRows.size(); ++k) {
                    int r = SRows[k], c = SCols[k];
                    int qidx = r*N + c;
                    if (DistGrid[idx][qidx] < Infinite)
                        EdgeCap[idx + 2][qidx + 2 + N*N] = Infinite;
                }
            }
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cin >> N >> Tval;
    memset(DistGrid, 0x3f, sizeof(DistGrid));
    for (int i = 0; i < N; ++i) cin >> GridIn[i];
    for (int i = 0; i < N; ++i) cin >> GridOut[i];
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            if (GridIn[i][j] == 'Z') {
                Zr = i;
                Zc = j;
            }
        }
    }
    BFS(Zr, Zc, DistGrid[Zr*N + Zc], false);
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            if (GridIn[i][j] >= '1' && GridIn[i][j] <= '9') {
                BFS(i, j, DistGrid[i*N + j], true);
            }
        }
    }
    BuildGraph();
    cout << FF_Algorithm(2 + N*N + N*N, 0, 1) << '\n';
    return 0;
}
